   <g class="viz-areas">${g.areas.map(a=>`<path d="${a.d}" class="area risk-${a.risk.toLowerCase()}" data-code="${esc(a.code)}" style="--d:${a.c?Math.round(a.c[0]/g.W*600):0}ms"/>`).join('')}</g>
