  if(ring){
   // Items sit on an ellipse; dashed arrows run clockwise between them.
   const n=items.length,W=760,H=430,cx=W/2,cy=H/2,rx=270,ry=150,p=a=>[cx+rx*Math.cos(a),cy+ry*Math.sin(a)],ang=k=>-Math.PI/2+k*2*Math.PI/n,id=uid('xp');
   const arcs=items.map((_,k)=>{const [x0,y0]=p(ang(k+.3)),[x1,y1]=p(ang(k+.7));return `<path class="xp-arc" d="M${x0.toFixed(1)} ${y0.toFixed(1)} A${rx} ${ry} 0 0 1 ${x1.toFixed(1)} ${y1.toFixed(1)}" marker-end="url(#${id})" style="--i:${k}"/>`;}).join('');
   body=`<div class="xp-cycle"><svg viewBox="0 0 ${W} ${H}" aria-hidden="true"><defs><marker id="${id}" viewBox="0 0 10 10" refX="7" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0L10 5L0 10z" fill="#f0c461"/></marker></defs>${arcs}</svg>
    ${t.title?`<div class="xp-hub">${esc(t.title)}</div>`:''}
    <ol>${items.map((it,k)=>{const [x,y]=p(ang(k));return card(it,k,`;left:${(x/W*100).toFixed(2)}%;top:${(y/H*100).toFixed(2)}%`).replace('<li ','<li class="xp-node" ');}).join('')}</ol></div>`;
  }else if(t.kind==='steps'||t.kind==='cycle'){
   body=`<ol class="xp-steps${t.kind==='cycle'?' is-loop':''}">${items.map((it,i)=>card(it,i).replace('<span class="xp-icon">',`<span class="xp-icon"><em>${i+1}</em>`)).join('')}</ol>${t.kind==='cycle'?`<p class="xp-loop">${icon('arrows-clockwise')} ${tr('Then it starts again')}</p>`:''}`;
  }else body=`<ul class="xp-facts">${items.map((it,i)=>card(it,i)).join('')}</ul>`;
